import { buildSeatComparison, thresholdReference, ratingForSeat } from './seat-outlook.js';
const labels={base:'不改选基础',current:'当前党团',solid:'稳固评级',likely:'较稳评级',lean:'倾向评级',tossup:'竞争胶着',unknown:'未知评级',vacant:'空缺'};
const sides={D:'民主党党团',R:'共和党党团',I:'独立未归团',T:'竞争胶着',U:'未知评级'};
export function comparisonHTML(roster,evidence,chamber,power,esc,side='D') {
 const m=buildSeatComparison(roster,evidence,chamber),ref=thresholdReference(power,chamber,m.capacity),occupied=thresholdReference(power,chamber,m.occupied);
 const description=s=>s.alignment==='T'||s.alignment==='U'?labels[s.kind]:sides[s.alignment]+' · '+labels[s.kind];
 const nums=value=>esc(value),fraction=ref.votes/m.capacity*100;
 const segments=group=>`<div class="seat-track" role="img" aria-label="${esc(group.segments.map(s=>description(s)+(s.independent?' · 独立议员':'')+' '+s.count).join('；'))}">${group.segments.map(s=>`<span class="seat-segment side-${s.alignment} kind-${s.kind}${s.independent?' is-independent':''}" style="flex-basis:${s.count/m.capacity*100}%" title="${esc(description(s))}${s.independent?' · 独立议员':''} · ${nums(s.count)}"></span>`).join('')}</div>`;
 const legend=group=>`<ol class="seat-key">${group.segments.map((s,i)=>`<li><i class="seat-segment side-${s.alignment} kind-${s.kind}${s.independent?' is-independent':''}"></i><span>${esc(description(s))}${s.independent?' · 独立议员':''}</span><b>${nums(s.count)}</b></li>`).join('')}</ol>`;
 const equations=['D','R'].map(side=>{const parts=m.outlook.segments.filter(s=>s.alignment===side);return `<p class="caucus-equation"><b>${side} ${nums(m.outlook.aligned[side])}</b><span>${parts.map(s=>`${esc(labels[s.kind])}${s.independent?'（独立议员）':''} ${nums(s.count)}`).join(' ＋ ')} ＝ ${nums(m.outlook.aligned[side])}</span></p>`;}).join('');
 const total=`<p class="seat-total">合计 ${nums(m.capacity)} · D ${nums(m.outlook.aligned.D)} ＋ R ${nums(m.outlook.aligned.R)}${m.outlook.aligned.I?' ＋ '+esc(sides.I)+' '+nums(m.outlook.aligned.I):''} ＋ 竞争胶着 ${nums(m.outlook.aligned.T)} ＋ 未知评级 ${nums(m.outlook.aligned.U)} ＝ ${nums(m.capacity)}</p>`;
 const mappedRatings=roster.seats.filter(s=>s.chamber===chamber).map(s=>ratingForSeat(s,evidence)).filter(Boolean),checked=[...new Set(mappedRatings.map(r=>r.asOf).filter(Boolean))],sources=[...new Set(mappedRatings.map(r=>r.source).filter(Boolean))];
 const provenance=`<p class="comparison-note">现任名单核验时间（UTC）：${esc(roster.asOf||'待核验')}<br>逐席评级核验时间（UTC）：${esc(checked.join(' · ')||'待核验')}<br>${sources.map(url=>`<a href="${esc(url)}" target="_blank" rel="noopener">评级原文 ↗</a>`).join(' · ')}</p>`;
 const gap=Math.max(0,ref.votes-m.current.aligned[side]),steps=m.steps[side];
 return `<div class="seat-comparison" data-capacity="${m.capacity}" data-threshold="${ref.votes}" data-reference-side="${side}">
 <article class="comparison-card"><h4>当前任期 · 党团席位</h4>${segments(m.current)}<div class="caucus-totals"><strong class="blue">D ${nums(m.current.aligned.D)}</strong><strong class="red">R ${nums(m.current.aligned.R)}</strong><span>空缺 ${nums(m.party.vacant)} · 合计 ${nums(m.capacity)}</span></div>${legend(m.current)}</article>
 <article class="comparison-card"><h4>选后情景 · 逐席来源评级</h4>${segments(m.outlook)}<div class="caucus-totals"><strong class="blue">D ${nums(m.outlook.aligned.D)}</strong><strong class="red">R ${nums(m.outlook.aligned.R)}</strong><span>竞争 ${nums(m.outlook.aligned.T)} · 未知 ${nums(m.outlook.aligned.U)} · 合计 ${nums(m.capacity)}</span></div>${legend(m.outlook)}</article></div>
 <div class="procedure-reference"><div class="comparison-controls"><h4>表决门槛 <strong>${nums(ref.votes)}</strong> 票</h4><div role="group" aria-label="门槛参考方向"><button data-threshold-side="D" aria-pressed="${side==='D'}">民主党党团</button><button data-threshold-side="R" aria-pressed="${side==='R'}">共和党党团</button></div></div><div class="vote-ruler" aria-label="所需赞成票（满员参考）"><span class="vote-frame" style="width:${fraction}%;${side==='R'?'right:0':'left:0'}"></span></div></div>
 <details class="power-rule"><summary>统计口径与来源</summary><p>${esc(power.labelZh)} · 所需赞成票（满员参考） ${nums(ref.votes)} · 参考分母 ${nums(m.capacity)}</p><p>一致党团口径 · 独立身份用紫色边框保留</p><p>当前席位构成，不是2024原始选举结果。</p><p>评级是类别，不是概率或得票率。</p>${total}${equations}<p>不改选基础 ${nums(m.retained)} · 已映射评级 ${nums(m.mapped)} / ${nums(m.contested)}</p>${m.outlook.aligned.U?'<p>未知评级保持未知，不按现任党派分配，也不视为平手。</p>':''}${provenance}<p>当前党籍：D ${nums(m.party.D)} · R ${nums(m.party.R)} · I ${nums(m.party.I)}</p><p>${esc(sides[side])} · 距满员参考：${nums(gap)} · 仅席位数差额，不是所缺实际赞成票。</p><p>${nums(steps[0])} → ${nums(steps[1])} → ${nums(steps[2])} · 基础＋稳固 → 加较稳 → 加倾向；类别累加，不是置信区间。</p><p>距满员参考：${nums(Math.max(0,ref.votes-steps[2]))}–${nums(Math.max(0,ref.votes-steps[0]))} · 未分配竞争与未知席。</p><p>中性框仅表示票数标尺，不选定任何议员，也不保证通过。</p><p>${esc(power.denominator)}</p>${m.occupied!==m.capacity?`<p>现任非空缺席位 ${nums(m.occupied)}；若全部计入本项分母，示例门槛 ${nums(occupied.votes)}。实际出席与投票须另行核验。</p>`:''}<p>${esc(power.thresholds.find(t=>t.chamber===chamber)?.tieBreaker||'')}</p></details>`;
}
